// Character classification helpers.
//
// PyYAML operates on sequences of Unicode code points, while JavaScript strings
// are sequences of UTF-16 code units.  Everything in this port that needs to
// reason about "characters" the way Python does works on arrays of code points
// produced by `toCodePoints`.
//
// No regular expressions are used anywhere in this library.

export function toCodePoints(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff && i + 1 < str.length) {
      const next = str.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        out.push(str.slice(i, i + 2));
        i++;
        continue;
      }
    }
    out.push(str[i]);
  }
  return out;
}

export function codePointLength(str) {
  let n = 0;
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff && i + 1 < str.length) {
      const next = str.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) i++;
    }
    n++;
  }
  return n;
}

// `ch in 'abc'` in Python, where ch may be '' (the empty string is a member of
// every string in Python, but PyYAML never relies on that) or a code point.
export function isIn(ch, set) {
  if (ch === '' || ch === null || ch === undefined) return false;
  return set.indexOf(ch) !== -1;
}

export const LINEBR = '\n  ';
export const FULL_LINEBR = '\r\n  ';
export const NULL_OR_LINEBR = '\0\r\n  ';
export const NULL_BL_LINEBR = '\0 \r\n  ';
export const NULL_BL_T_LINEBR = '\0 \t\r\n  ';
export const NULL_BL_T = '\0 \t';
export const SPACES_AND_BREAKS = ' \r\n  ';

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isHex(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

export function isAlnumOrDash(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
    ch === '-' || ch === '_';
}

// Python's `ord()` for a single code point.
export function ord(ch) {
  return ch.codePointAt(0);
}

// Left-padded uppercase hexadecimal, i.e. '%0<n>X' in Python.
export function hexUpper(value, width) {
  let s = value.toString(16).toUpperCase();
  while (s.length < width) s = '0' + s;
  return s;
}

export function repeat(str, count) {
  return count > 0 ? str.repeat(count) : '';
}

// The set of code points the PyYAML reader accepts:
//   [\x09\x0A\x0D\x20-\x7E\x85\xA0-퟿-�\U00010000-\U0010FFFF]
export function isPrintable(cp) {
  if (cp === 0x09 || cp === 0x0a || cp === 0x0d || cp === 0x85) return true;
  if (cp >= 0x20 && cp <= 0x7e) return true;
  if (cp >= 0xa0 && cp <= 0xd7ff) return true;
  if (cp >= 0xe000 && cp <= 0xfffd) return true;
  if (cp >= 0x10000 && cp <= 0x10ffff) return true;
  return false;
}

