export const FULL_LINEBR = '\r' + LINEBR;
export const NULL_OR_LINEBR = '\0' + FULL_LINEBR;
export const NULL_BL_LINEBR = '\0 ' + FULL_LINEBR;
export const NULL_BL_T_LINEBR = '\0 \t' + FULL_LINEBR;
export const NULL_BL_T = '\0 \t';
export const SPACES_AND_BREAKS = ' ' + FULL_LINEBR;
export const BREAKS_NO_CR = LINEBR;

