// Error types and source position marks, mirroring yaml/error.py.
//
// Only the *behaviour* the entry point depends on matters for stdout alignment
// (a raised error means nothing is printed and the process exits non-zero), but
// the messages are reproduced faithfully so stderr is recognisable too.

import { isIn, FULL_LINEBR, repeat } from './chars.mjs';

export class Mark {
  // `buffer` is an array of code points (the reader's buffer) and `pointer` is
  // an index into it.
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer;
    this.pointer = pointer;
  }

  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null || this.buffer === undefined) return null;
    let head = '';
    let start = this.pointer;
    while (start > 0 && !isIn(this.buffer[start - 1], '\0' + FULL_LINEBR)) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    let tail = '';
    let end = this.pointer;
    while (end < this.buffer.length && !isIn(this.buffer[end], '\0' + FULL_LINEBR)) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ... ';
        break;
      }
    }
    const snippet = this.buffer.slice(start, end).join('');
    return repeat(' ', indent) + head + snippet + tail + '\n' +
      repeat(' ', indent + this.pointer - start + head.length) + '^';
  }

  toString() {
    const snippet = this.getSnippet();
    let where = '  in "' + this.name + '", line ' + (this.line + 1) +
      ', column ' + (this.column + 1);
    if (snippet !== null) where += ':\n' + snippet;
    return where;
  }
}

export class YAMLError extends Error {
  constructor(message) {
    super(message);
    this.name = 'YAMLError';
    this.pythonType = 'yaml.error.YAMLError';
  }
}

export class MarkedYAMLError extends YAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super('');
    this.context = context === undefined ? null : context;
    this.contextMark = contextMark === undefined ? null : contextMark;
    this.problem = problem === undefined ? null : problem;
    this.problemMark = problemMark === undefined ? null : problemMark;
    this.note = note === undefined ? null : note;
    this.message = this.describe();
  }

  describe() {
    const lines = [];
    if (this.context !== null) lines.push(this.context);
    if (this.contextMark !== null &&
      (this.problem === null || this.problemMark === null ||
        this.contextMark.name !== this.problemMark.name ||
        this.contextMark.line !== this.problemMark.line ||
        this.contextMark.column !== this.problemMark.column)) {
      lines.push(this.contextMark.toString());
    }
    if (this.problem !== null) lines.push(this.problem);
    if (this.problemMark !== null) lines.push(this.problemMark.toString());
    if (this.note !== null) lines.push(this.note);
    return lines.join('\n');
  }
}

function markedSubclass(name, pythonType) {
  return class extends MarkedYAMLError {
    constructor(context, contextMark, problem, problemMark, note) {
      super(context, contextMark, problem, problemMark, note);
      this.name = name;
      this.pythonType = pythonType;
    }
  };
}

export const ScannerError = markedSubclass('ScannerError', 'yaml.scanner.ScannerError');
export const ParserError = markedSubclass('ParserError', 'yaml.parser.ParserError');
export const ComposerError = markedSubclass('ComposerError', 'yaml.composer.ComposerError');
export const ConstructorError = markedSubclass('ConstructorError', 'yaml.constructor.ConstructorError');

export class ReaderError extends YAMLError {
  constructor(name, position, character, encoding, reason) {
    super('');
    this.name = 'ReaderError';
    this.pythonType = 'yaml.reader.ReaderError';
    this.streamName = name;
    this.position = position;
    this.character = character;
    this.encoding = encoding;
    this.reason = reason;
    this.message = 'unacceptable character #x' +
      character.toString(16).padStart(4, '0') + ': ' + reason + '\n' +
      '  in "' + this.streamName + '", position ' + position;
  }
}

export class EmitterError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'EmitterError';
    this.pythonType = 'yaml.emitter.EmitterError';
  }
}

export class SerializerError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'SerializerError';
    this.pythonType = 'yaml.serializer.SerializerError';
  }
}

export class RepresenterError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'RepresenterError';
    this.pythonType = 'yaml.representer.RepresenterError';
  }
}

// Plain Python exceptions that escape PyYAML uncaught for some inputs, e.g.
// `!!int "abc"` raises ValueError and `!!bool "maybe"` raises KeyError.
export class PythonError extends Error {
  constructor(pythonType, message) {
    super(message);
    this.name = pythonType;
    this.pythonType = pythonType;
  }
}

export function valueError(message) {
  return new PythonError('ValueError', message);
}

export function keyError(repr) {
  return new PythonError('KeyError', repr);
}

export function typeError(message) {
  return new PythonError('TypeError', message);
}

export function indexError(message) {
  return new PythonError('IndexError', message);
}

export function attributeError(message) {
  return new PythonError('AttributeError', message);
}

export function binasciiError(message) {
  return new PythonError('binascii.Error', message);
}

