// A small model of the Python runtime values that `yaml.safe_load` can produce,
// with the equality, hashing, ordering and repr rules the dumper depends on.
//
// Every value is a plain object tagged with `kind`, so `int` and `float` stay
// distinguishable (Python's `1` and `1.0` dump very differently) and integers
// keep arbitrary precision.

import { typeError } from './errors.mjs';
import { formatFloatRepr } from './pyfloat.mjs';

export const NONE = { kind: 'none' };
export const TRUE = { kind: 'bool', value: true };
export const FALSE = { kind: 'bool', value: false };

export function pyBool(value) {
  return value ? TRUE : FALSE;
}

export function pyInt(value) {
  return { kind: 'int', value: BigInt(value) };
}

export function pyFloat(value) {
  return { kind: 'float', value: value };
}

export function pyStr(value) {
  return { kind: 'str', value: value };
}

export function pyBytes(bytes) {
  return { kind: 'bytes', value: bytes };
}

export function pyList(items) {
  return { kind: 'list', items: items || [] };
}

export function pyTuple(items) {
  return { kind: 'tuple', items: items || [] };
}

export function pyDate(year, month, day) {
  return { kind: 'date', year: year, month: month, day: day };
}

// `tzMinutes` is null for a naive datetime, otherwise the UTC offset in minutes.
export function pyDateTime(year, month, day, hour, minute, second, microsecond, tzMinutes) {
  return {
    kind: 'datetime',
    year: year,
    month: month,
    day: day,
    hour: hour,
    minute: minute,
    second: second,
    microsecond: microsecond,
    tzMinutes: tzMinutes === undefined ? null : tzMinutes,
  };
}

export function pyTypeName(value) {
  switch (value.kind) {
    case 'none': return 'NoneType';
    case 'bool': return 'bool';
    case 'int': return 'int';
    case 'float': return 'float';
    case 'str': return 'str';
    case 'bytes': return 'bytes';
    case 'list': return 'list';
    case 'tuple': return 'tuple';
    case 'dict': return 'dict';
    case 'set': return 'set';
    case 'date': return 'date';
    case 'datetime': return 'datetime';
    default: return value.kind;
  }
}

export function isHashable(value) {
  switch (value.kind) {
    case 'list':
    case 'dict':
    case 'set':
      return false;
    case 'tuple':
      return value.items.every(isHashable);
    default:
      return true;
  }
}

// A string that collides exactly when Python's hash/eq would.  `1`, `1.0` and
// `True` all map to the same key, which is what makes `{1: 'a', true: 'b'}`
// collapse to a single entry.
export function hashKey(value) {
  switch (value.kind) {
    case 'none': return 'N';
    case 'bool': return 'i' + (value.value ? '1' : '0');
    case 'int': return 'i' + value.value.toString();
    case 'float': {
      const v = value.value;
      if (Number.isNaN(v)) return 'f:nan';
      if (v === Infinity) return 'f:inf';
      if (v === -Infinity) return 'f:-inf';
      if (Number.isInteger(v)) return 'i' + BigInt(v).toString();
      return 'f:' + v.toString();
    }
    case 'str': return 's' + value.value;
    case 'bytes': return 'b' + Array.from(value.value).join(',');
    case 'date': return 'd' + value.year + '-' + value.month + '-' + value.day;
    case 'datetime': return 'D' + isoDateTime(value, ' ');
    case 'tuple': return 't(' + value.items.map(hashKey).join('') + ')';
    default: return 'x' + value.kind;
  }
}

export function pyEq(a, b) {
  if (a === b) return true;
  const na = isNumberKind(a);
  const nb = isNumberKind(b);
  if (na && nb) return numericCompare(a, b) === 0;
  if (a.kind !== b.kind) return false;
  switch (a.kind) {
    case 'none': return true;
    case 'str': return a.value === b.value;
    case 'bytes': return hashKey(a) === hashKey(b);
    case 'date': return a.year === b.year && a.month === b.month && a.day === b.day;
    case 'datetime': return dateTimeCompare(a, b) === 0;
    case 'tuple':
      if (a.items.length !== b.items.length) return false;
      for (let i = 0; i < a.items.length; i++) {
        if (!pyEq(a.items[i], b.items[i])) return false;
      }
      return true;
    default: return false;
  }
}

function isNumberKind(v) {
  return v.kind === 'int' || v.kind === 'float' || v.kind === 'bool';
}

function asBig(v) {
  if (v.kind === 'int') return v.value;
  return v.value ? 1n : 0n;
}

// Exact comparison across int/float/bool; returns -1, 0, 1, or NaN when one
// operand is a NaN float (every comparison with NaN is False in Python).
function numericCompare(a, b) {
  const aFloat = a.kind === 'float';
  const bFloat = b.kind === 'float';
  if (aFloat && Number.isNaN(a.value)) return NaN;
  if (bFloat && Number.isNaN(b.value)) return NaN;
  if (aFloat && bFloat) return a.value < b.value ? -1 : (a.value > b.value ? 1 : 0);
  if (!aFloat && !bFloat) {
    const x = asBig(a);
    const y = asBig(b);
    return x < y ? -1 : (x > y ? 1 : 0);
  }
  // One integer, one float: compare exactly.
  const intVal = aFloat ? asBig(b) : asBig(a);
  const floatVal = aFloat ? a.value : b.value;
  let sign;
  if (floatVal === Infinity) sign = -1;
  else if (floatVal === -Infinity) sign = 1;
  else {
    const truncated = Math.trunc(floatVal);
    const floatInt = BigInt(truncated);
    if (intVal < floatInt) sign = -1;
    else if (intVal > floatInt) sign = 1;
    else {
      const fraction = floatVal - truncated;
      sign = fraction > 0 ? -1 : (fraction < 0 ? 1 : 0);
    }
  }
  // `sign` compares int against float; flip when the float came first.
  return aFloat ? -sign : sign;
}

function dateTimeCompare(a, b) {
  const awareA = a.tzMinutes !== null;
  const awareB = b.tzMinutes !== null;
  if (awareA !== awareB) {
    throw typeError("can't compare offset-naive and offset-aware datetimes");
  }
  const ka = dateTimeSortKey(a);
  const kb = dateTimeSortKey(b);
  return ka < kb ? -1 : (ka > kb ? 1 : 0);
}

function dateTimeSortKey(value) {
  // Microseconds since a fixed epoch, offset-adjusted for aware datetimes.
  const days = BigInt(daysFromCivil(value.year, value.month, value.day));
  let micros = days * 86400000000n +
    BigInt(value.hour) * 3600000000n +
    BigInt(value.minute) * 60000000n +
    BigInt(value.second) * 1000000n +
    BigInt(value.microsecond);
  if (value.tzMinutes !== null) micros -= BigInt(value.tzMinutes) * 60000000n;
  return micros;
}

export function daysFromCivil(y, m, d) {
  let year = y;
  year -= m <= 2 ? 1 : 0;
  const era = Math.floor(year / 400);
  const yoe = year - era * 400;
  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

function comparisonClass(value) {
  switch (value.kind) {
    case 'int':
    case 'float':
    case 'bool':
