// Python's `repr(float)` and `float(str)`.
//
// CPython prints the shortest decimal string that round-trips, switching to
// exponential notation when the decimal point lands at position <= -4 or > 16.
// JavaScript's `toExponential()` with no argument yields exactly the same
// shortest digit string, so only the formatting rules have to be reproduced.

import { valueError } from './errors.mjs';

function shortestDigits(value) {
  // value is finite and strictly positive here.
  const text = value.toExponential();
  const eIndex = text.indexOf('e');
  const mantissa = text.slice(0, eIndex);
  const exponent = Number(text.slice(eIndex + 1));
  const dot = mantissa.indexOf('.');
  const digits = dot === -1 ? mantissa : mantissa.slice(0, dot) + mantissa.slice(dot + 1);
  // Strip any trailing zeros toExponential may have produced (it does not, but
  // being defensive keeps `decpt` honest).
  let end = digits.length;
  while (end > 1 && digits[end - 1] === '0') end--;
  return { digits: digits.slice(0, end), decpt: exponent + 1 };
}

function padExponent(value) {
  const sign = value < 0 ? '-' : '+';
  let abs = String(Math.abs(value));
  if (abs.length < 2) abs = '0' + abs;
  return 'e' + sign + abs;
}

export function formatFloatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
