  const table = new Map();
  for (let i = 0; i < 10; i++) table.set(String(i), i);
  for (let i = 0; i < 26; i++) {
    table.set(String.fromCharCode(97 + i), 10 + i);
    table.set(String.fromCharCode(65 + i), 10 + i);
  }
  return table;
})();

const BASE_PREFIXES = { 2: 'b', 8: 'o', 16: 'x' };

// Returns a BigInt.  Accepts surrounding whitespace, an optional sign, the
// base-matching literal prefix (0b/0o/0x) and underscores between digits, which
// is exactly what CPython accepts.
export function pythonInt(text, base = 10) {
  const raw = text;
  let s = stripPythonWhitespace(text);
  let negative = false;
  if (s[0] === '+' || s[0] === '-') {
    negative = s[0] === '-';
    s = s.slice(1);
  }
  const prefix = BASE_PREFIXES[base];
  if (prefix && s.length > 2 && s[0] === '0' &&
    (s[1] === prefix || s[1] === prefix.toUpperCase())) {
    s = s.slice(2);
  }
  if (s.length === 0) throw invalidLiteral(raw, base);
  let value = 0n;
  const bigBase = BigInt(base);
  let previousWasDigit = false;
  let digitCount = 0;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '_') {
      if (!previousWasDigit || i + 1 >= s.length) throw invalidLiteral(raw, base);
      previousWasDigit = false;
      continue;
