// CPython's list.sort() reproduced closely enough that a comparison which
// raises TypeError raises it at the same point.
//
// PyYAML sorts a mapping's (key, value) pairs with a bare `sorted(...)` wrapped
// in `try/except TypeError`, so whether the sort raises decides whether the
// output is sorted or left in insertion order.  For runs shorter than 64
// elements CPython uses count_run + binarysort, which is what `sortRun`
// implements verbatim; longer lists additionally merge, and merging only ever
// happens between already-ordered runs so a plain stable merge matches.

const MIN_RUN_CAP = 64;

function mergeComputeMinrun(n) {
  let r = 0;
  let size = n;
  while (size >= MIN_RUN_CAP) {
    r |= size & 1;
    size >>= 1;
  }
  return size + r;
}

// count_run(): length of the initial ascending (or strictly descending) run.
function countRun(items, lo, hi, lessThan) {
  let n = 2;
  let i = lo + 1;
  if (i === hi) return { length: 1, descending: false };
  let descending = false;
  if (lessThan(items[i], items[i - 1])) {
    descending = true;
    for (i = i + 1; i < hi; i++, n++) {
      if (!lessThan(items[i], items[i - 1])) break;
    }
  } else {
    for (i = i + 1; i < hi; i++, n++) {
      if (lessThan(items[i], items[i - 1])) break;
    }
  }
  return { length: n, descending: descending };
}

function reverseSlice(items, lo, hi) {
  let i = lo;
  let j = hi - 1;
  while (i < j) {
    const tmp = items[i];
    items[i] = items[j];
    items[j] = tmp;
    i++;
    j--;
  }
}

// binarysort(): binary insertion sort of items[start:hi] into the sorted
// items[lo:start].
function binarySort(items, lo, hi, start, lessThan) {
  for (; start < hi; start++) {
    let l = lo;
    let r = start;
    const pivot = items[start];
    do {
      const p = l + ((r - l) >> 1);
      if (lessThan(pivot, items[p])) r = p;
      else l = p + 1;
    } while (l < r);
    for (let p = start; p > l; p--) items[p] = items[p - 1];
    items[l] = pivot;
  }
}

function mergeRuns(items, lo, mid, hi, lessThan) {
  const left = items.slice(lo, mid);
  const right = items.slice(mid, hi);
  let i = 0;
  let j = 0;
  let k = lo;
  while (i < left.length && j < right.length) {
    // Stable: take from the left run unless the right element is strictly less.
    if (lessThan(right[j], left[i])) items[k++] = right[j++];
    else items[k++] = left[i++];
  }
  while (i < left.length) items[k++] = left[i++];
  while (j < right.length) items[k++] = right[j++];
}

// Sorts a copy of `input`; any exception thrown by `lessThan` propagates, and
// the caller's original array is untouched, matching `sorted()`.
export function pySorted(input, lessThan) {
  const items = input.slice();
  const n = items.length;
  if (n < 2) return items;
  const minrun = mergeComputeMinrun(n);
  const runs = [];
  let lo = 0;
  while (lo < n) {
    const { length, descending } = countRun(items, lo, n, lessThan);
    let runLength = length;
    if (descending) reverseSlice(items, lo, lo + runLength);
    if (runLength < minrun) {
      const force = Math.min(n - lo, minrun);
      binarySort(items, lo, lo + force, lo + runLength, lessThan);
      runLength = force;
    }
    runs.push([lo, lo + runLength]);
    lo += runLength;
  }
  while (runs.length > 1) {
    const b = runs.pop();
    const a = runs.pop();
    mergeRuns(items, a[0], a[1], b[1], lessThan);
    runs.push([a[0], b[1]]);
  }
  return items;
}

