// base64 as the `base64` / `binascii` modules do it.
//
// `base64.encodebytes` wraps at 76 characters and always ends with a newline;
// `base64.decodebytes` delegates to `binascii.a2b_base64` in non-strict mode,
// which silently discards characters outside the alphabet and only complains
// about a truncated final quantum.

import { binasciiError } from './errors.mjs';

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const PAD = '=';

const REVERSE = (() => {
  const table = new Map();
  for (let i = 0; i < ALPHABET.length; i++) table.set(ALPHABET[i], i);
  return table;
})();

export function encodebytes(bytes) {
  let out = '';
  let lineLength = 0;
  for (let i = 0; i < bytes.length; i += 3) {
    const remaining = bytes.length - i;
    const b0 = bytes[i];
    const b1 = remaining > 1 ? bytes[i + 1] : 0;
    const b2 = remaining > 2 ? bytes[i + 2] : 0;
    let chunk = ALPHABET[b0 >> 2] + ALPHABET[((b0 & 0x03) << 4) | (b1 >> 4)];
    chunk += remaining > 1 ? ALPHABET[((b1 & 0x0f) << 2) | (b2 >> 6)] : PAD;
    chunk += remaining > 2 ? ALPHABET[b2 & 0x3f] : PAD;
    out += chunk;
    lineLength += 4;
    if (lineLength >= 76) {
      out += '\n';
      lineLength = 0;
    }
  }
  if (bytes.length === 0) return '';
  if (lineLength !== 0) out += '\n';
  return out;
}

export function decodebytes(text) {
  const out = [];
  let quadPos = 0;
  let leftchar = 0;
  let pads = 0;
  let dataChars = 0;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === PAD) {
      pads++;
      if (quadPos >= 2 && quadPos + pads >= 4) {
        return Uint8Array.from(out);
      }
      continue;
    }
    const value = REVERSE.get(ch);
    if (value === undefined) continue;
    pads = 0;
    dataChars++;
    switch (quadPos) {
      case 0:
        quadPos = 1;
        leftchar = value;
        break;
      case 1:
        quadPos = 2;
        out.push(((leftchar << 2) | (value >> 4)) & 0xff);
        leftchar = value & 0x0f;
        break;
      case 2:
        quadPos = 3;
        out.push(((leftchar << 4) | (value >> 2)) & 0xff);
        leftchar = value & 0x03;
        break;
      case 3:
        quadPos = 0;
        out.push(((leftchar << 6) | value) & 0xff);
        leftchar = 0;
        break;
      default:
        break;
    }
  }
  if (quadPos !== 0) {
    if (quadPos === 1) {
      throw binasciiError('Invalid base64-encoded string: number of data ' +
        'characters (' + dataChars + ') cannot be 1 more than a multiple of 4');
    }
    throw binasciiError('Incorrect padding');
  }
  return Uint8Array.from(out);
}

// PyYAML decodes the scalar's UTF-8 bytes; every base64 character is ASCII so a
// per-code-unit conversion is faithful for the alphabet, and non-alphabet
// characters are discarded either way.
export function utf8Encode(text) {
  return new TextEncoder().encode(text);
}

export function utf8DecodeAscii(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; i++) out += String.fromCharCode(bytes[i]);
  return out;
}

