    switch (quadPos) {
      case 0:
        quadPos = 1;
        leftchar = value;
        break;
      case 1:
        quadPos = 2;
        out.push(((leftchar << 2) | (value >> 4)) & 0xff);
        leftchar = value & 0x0f;
        break;
      case 2:
        quadPos = 3;
        out.push(((leftchar << 4) | (value >> 2)) & 0xff);
        leftchar = value & 0x03;
        break;
      case 3:
        quadPos = 0;
        out.push(((leftchar << 6) | value) & 0xff);
        leftchar = 0;
        break;
      default:
        break;
    }
  }
  if (quadPos !== 0) {
    if (quadPos === 1) {
      throw binasciiError('Invalid base64-encoded string: number of data ' +
        'characters (' + dataChars + ') cannot be 1 more than a multiple of 4');
    }
    throw binasciiError('Incorrect padding');
  }
  return Uint8Array.from(out);
}

// PyYAML decodes the scalar's UTF-8 bytes; every base64 character is ASCII so a
// per-code-unit conversion is faithful for the alphabet, and non-alphabet
// characters are discarded either way.
export function utf8Encode(text) {
  return new TextEncoder().encode(text);
}

export function utf8DecodeAscii(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; i++) out += String.fromCharCode(bytes[i]);
  return out;
}

