// yaml/reader.py — a code-point cursor over the input string.

import { Mark, ReaderError } from './errors.mjs';
import { toCodePoints, isPrintable, isIn, LINEBR, BOM } from './chars.mjs';

export class Reader {
  constructor(text) {
    this.name = '<unicode string>';
    this.checkPrintable(text);
    this.buffer = toCodePoints(text);
    this.buffer.push('\0');
    this.pointer = 0;
    this.index = 0;
    this.line = 0;
    this.column = 0;
  }

  checkPrintable(text) {
    let position = 0;
    for (const ch of text) {
      const cp = ch.codePointAt(0);
      if (!isPrintable(cp)) {
        throw new ReaderError(this.name, position, cp, 'unicode',
          'special characters are not allowed');
      }
      position++;
    }
  }

  peek(index = 0) {
    const ch = this.buffer[this.pointer + index];
    return ch === undefined ? '\0' : ch;
  }

  prefix(length = 1) {
    return this.buffer.slice(this.pointer, this.pointer + length).join('');
  }

  forward(length = 1) {
    let remaining = length;
    while (remaining) {
      const ch = this.buffer[this.pointer];
      if (ch === undefined) break;
      this.pointer += 1;
      this.index += 1;
      if (isIn(ch, LINEBR) || (ch === '\r' && this.peek() !== '\n')) {
        this.line += 1;
        this.column = 0;
      } else if (ch !== BOM) {
        this.column += 1;
      }
      remaining -= 1;
    }
  }

  getMark() {
    return new Mark(this.name, this.index, this.line, this.column,
      this.buffer, this.pointer);
  }
}

