// yaml/tokens.py — token constructors.
//
// `type` is used for dispatch, `id` is the spelling that appears in parser
// error messages.

function makeToken(type, id, startMark, endMark, extra) {
  const token = { type: type, id: id, startMark: startMark, endMark: endMark };
  if (extra) Object.assign(token, extra);
  return token;
}

export const TOKEN = {
  STREAM_START: 'StreamStart',
  STREAM_END: 'StreamEnd',
  DIRECTIVE: 'Directive',
  DOCUMENT_START: 'DocumentStart',
  DOCUMENT_END: 'DocumentEnd',
  BLOCK_SEQUENCE_START: 'BlockSequenceStart',
  BLOCK_MAPPING_START: 'BlockMappingStart',
  BLOCK_END: 'BlockEnd',
  FLOW_SEQUENCE_START: 'FlowSequenceStart',
  FLOW_MAPPING_START: 'FlowMappingStart',
  FLOW_SEQUENCE_END: 'FlowSequenceEnd',
  FLOW_MAPPING_END: 'FlowMappingEnd',
  KEY: 'Key',
  VALUE: 'Value',
  BLOCK_ENTRY: 'BlockEntry',
  FLOW_ENTRY: 'FlowEntry',
  ALIAS: 'Alias',
  ANCHOR: 'Anchor',
  TAG: 'Tag',
  SCALAR: 'Scalar',
};

export const streamStartToken = (s, e, encoding) =>
  makeToken(TOKEN.STREAM_START, '<stream start>', s, e, { encoding: encoding || null });
export const streamEndToken = (s, e) =>
  makeToken(TOKEN.STREAM_END, '<stream end>', s, e);
export const directiveToken = (name, value, s, e) =>
  makeToken(TOKEN.DIRECTIVE, '<directive>', s, e, { name: name, value: value });
export const documentStartToken = (s, e) =>
  makeToken(TOKEN.DOCUMENT_START, '<document start>', s, e);
export const documentEndToken = (s, e) =>
  makeToken(TOKEN.DOCUMENT_END, '<document end>', s, e);
export const blockSequenceStartToken = (s, e) =>
  makeToken(TOKEN.BLOCK_SEQUENCE_START, '<block sequence start>', s, e);
export const blockMappingStartToken = (s, e) =>
  makeToken(TOKEN.BLOCK_MAPPING_START, '<block mapping start>', s, e);
export const blockEndToken = (s, e) =>
  makeToken(TOKEN.BLOCK_END, '<block end>', s, e);
export const flowSequenceStartToken = (s, e) =>
  makeToken(TOKEN.FLOW_SEQUENCE_START, '[', s, e);
export const flowMappingStartToken = (s, e) =>
  makeToken(TOKEN.FLOW_MAPPING_START, '{', s, e);
export const flowSequenceEndToken = (s, e) =>
  makeToken(TOKEN.FLOW_SEQUENCE_END, ']', s, e);
export const flowMappingEndToken = (s, e) =>
  makeToken(TOKEN.FLOW_MAPPING_END, '}', s, e);
export const keyToken = (s, e) => makeToken(TOKEN.KEY, '?', s, e);
export const valueToken = (s, e) => makeToken(TOKEN.VALUE, ':', s, e);
export const blockEntryToken = (s, e) => makeToken(TOKEN.BLOCK_ENTRY, '-', s, e);
export const flowEntryToken = (s, e) => makeToken(TOKEN.FLOW_ENTRY, ',', s, e);
export const aliasToken = (value, s, e) =>
  makeToken(TOKEN.ALIAS, '<alias>', s, e, { value: value });
export const anchorToken = (value, s, e) =>
  makeToken(TOKEN.ANCHOR, '<anchor>', s, e, { value: value });
export const tagToken = (value, s, e) =>
  makeToken(TOKEN.TAG, '<tag>', s, e, { value: value });
export const scalarToken = (value, plain, s, e, style) =>
  makeToken(TOKEN.SCALAR, '<scalar>', s, e,
    { value: value, plain: plain, style: style === undefined ? null : style });

