// yaml/scanner.py — turns the character stream into tokens.
//
// A direct port: the control flow, the order of checks and the error messages
// all follow the original, because the block/flow indentation rules and the
// "simple key" bookkeeping are what decide whether a document parses at all.

import { ScannerError } from './errors.mjs';
import { strRepr } from './pyvalues.mjs';
import {
  isIn, isAlnumOrDash, isDigit, isHex,
  LINEBR, FULL_LINEBR, NULL_OR_LINEBR, NULL_BL_LINEBR, NULL_BL_T_LINEBR,
  NULL_BL_T, BOM, NEL, LS, PS,
} from './chars.mjs';
import {
  streamStartToken, streamEndToken, directiveToken, documentStartToken,
  documentEndToken, blockSequenceStartToken, blockMappingStartToken,
  blockEndToken, flowSequenceStartToken, flowMappingStartToken,
  flowSequenceEndToken, flowMappingEndToken, keyToken, valueToken,
  blockEntryToken, flowEntryToken, aliasToken, anchorToken, tagToken,
  scalarToken, TOKEN,
} from './tokens.mjs';

const ESCAPE_REPLACEMENTS = (() => {
  const map = new Map();
  map.set('0', '\0');
  map.set('a', '\x07');
  map.set('b', '\x08');
  map.set('t', '\x09');
  map.set('\t', '\x09');
  map.set('n', '\x0a');
  map.set('v', '\x0b');
  map.set('f', '\x0c');
  map.set('r', '\x0d');
  map.set('e', '\x1b');
  map.set(' ', '\x20');
  map.set('"', '"');
  map.set('\\', '\\');
  map.set('/', '/');
  map.set('N', NEL);
  map.set('_', String.fromCharCode(0xa0));
  map.set('L', LS);
  map.set('P', PS);
  return map;
})();

const ESCAPE_CODES = new Map([['x', 2], ['u', 4], ['U', 8]]);

const HEX_DIGITS = '0123456789ABCDEFabcdef';

class SimpleKey {
  constructor(tokenNumber, required, index, line, column, mark) {
    this.tokenNumber = tokenNumber;
    this.required = required;
    this.index = index;
    this.line = line;
    this.column = column;
    this.mark = mark;
  }
}

export class Scanner {
  constructor(reader) {
    this.reader = reader;
    this.done = false;
    this.flowLevel = 0;
    this.tokens = [];
    this.fetchStreamStart();
    this.tokensTaken = 0;
    this.indent = -1;
    this.indents = [];
    this.allowSimpleKey = true;
    this.possibleSimpleKeys = new Map();
  }

  // -- Reader delegation ---------------------------------------------------

  peek(index = 0) { return this.reader.peek(index); }
  prefix(length = 1) { return this.reader.prefix(length); }
  forward(length = 1) { this.reader.forward(length); }
  getMark() { return this.reader.getMark(); }
  get column() { return this.reader.column; }
  get line() { return this.reader.line; }
  get index() { return this.reader.index; }

  // -- Token stream --------------------------------------------------------

  checkToken(...types) {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length) {
      if (!types.length) return true;
      for (const type of types) {
        if (this.tokens[0].type === type) return true;
      }
    }
    return false;
  }

  peekToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    return this.tokens.length ? this.tokens[0] : null;
  }

  getToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length) {
      this.tokensTaken += 1;
      return this.tokens.shift();
    }
    return null;
  }

  needMoreTokens() {
    if (this.done) return false;
    if (!this.tokens.length) return true;
    this.stalePossibleSimpleKeys();
    return this.nextPossibleSimpleKey() === this.tokensTaken;
  }

  fetchMoreTokens() {
    this.scanToNextToken();
    this.stalePossibleSimpleKeys();
    this.unwindIndent(this.column);
    const ch = this.peek();
    if (ch === '\0') return this.fetchStreamEnd();
    if (ch === '%' && this.checkDirective()) return this.fetchDirective();
    if (ch === '-' && this.checkDocumentStart()) return this.fetchDocumentStart();
    if (ch === '.' && this.checkDocumentEnd()) return this.fetchDocumentEnd();
    if (ch === '[') return this.fetchFlowSequenceStart();
    if (ch === '{') return this.fetchFlowMappingStart();
    if (ch === ']') return this.fetchFlowSequenceEnd();
    if (ch === '}') return this.fetchFlowMappingEnd();
    if (ch === ',') return this.fetchFlowEntry();
    if (ch === '-' && this.checkBlockEntry()) return this.fetchBlockEntry();
    if (ch === '?' && this.checkKey()) return this.fetchKey();
    if (ch === ':' && this.checkValue()) return this.fetchValue();
    if (ch === '*') return this.fetchAlias();
    if (ch === '&') return this.fetchAnchor();
    if (ch === '!') return this.fetchTag();
    if (ch === '|' && !this.flowLevel) return this.fetchLiteral();
    if (ch === '>' && !this.flowLevel) return this.fetchFolded();
    if (ch === "'") return this.fetchSingle();
    if (ch === '"') return this.fetchDouble();
    if (this.checkPlain()) return this.fetchPlain();
    throw new ScannerError('while scanning for the next token', null,
      'found character ' + strRepr(ch) + ' that cannot start any token',
      this.getMark());
  }

  // -- Simple keys ---------------------------------------------------------

  nextPossibleSimpleKey() {
    let minTokenNumber = null;
    for (const key of this.possibleSimpleKeys.values()) {
      if (minTokenNumber === null || key.tokenNumber < minTokenNumber) {
        minTokenNumber = key.tokenNumber;
      }
    }
    return minTokenNumber;
  }

  stalePossibleSimpleKeys() {
    for (const level of Array.from(this.possibleSimpleKeys.keys())) {
      const key = this.possibleSimpleKeys.get(level);
      if (key.line !== this.line || this.index - key.index > 1024) {
        if (key.required) {
          throw new ScannerError('while scanning a simple key', key.mark,
            "could not find expected ':'", this.getMark());
        }
        this.possibleSimpleKeys.delete(level);
      }
    }
  }

  savePossibleSimpleKey() {
    const required = !this.flowLevel && this.indent === this.column;
    if (this.allowSimpleKey) {
      this.removePossibleSimpleKey();
      const tokenNumber = this.tokensTaken + this.tokens.length;
      const key = new SimpleKey(tokenNumber, required, this.index, this.line,
        this.column, this.getMark());
      this.possibleSimpleKeys.set(this.flowLevel, key);
    }
  }

  removePossibleSimpleKey() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      if (key.required) {
        throw new ScannerError('while scanning a simple key', key.mark,
          "could not find expected ':'", this.getMark());
      }
      this.possibleSimpleKeys.delete(this.flowLevel);
    }
  }

  // -- Indentation ---------------------------------------------------------

  unwindIndent(column) {
    if (this.flowLevel) return;
    while (this.indent > column) {
      const mark = this.getMark();
      this.indent = this.indents.pop();
      this.tokens.push(blockEndToken(mark, mark));
    }
  }

  addIndent(column) {
    if (this.indent < column) {
      this.indents.push(this.indent);
      this.indent = column;
      return true;
    }
    return false;
  }

  // -- Fetchers ------------------------------------------------------------

  fetchStreamStart() {
    const mark = this.getMark();
    this.tokens.push(streamStartToken(mark, mark, null));
  }

  fetchStreamEnd() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.possibleSimpleKeys = new Map();
    const mark = this.getMark();
    this.tokens.push(streamEndToken(mark, mark));
    this.done = true;
  }

  fetchDirective() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanDirective());
  }

  fetchDocumentStart() { this.fetchDocumentIndicator(documentStartToken); }
  fetchDocumentEnd() { this.fetchDocumentIndicator(documentEndToken); }

  fetchDocumentIndicator(make) {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward(3);
    this.tokens.push(make(startMark, this.getMark()));
  }

  fetchFlowSequenceStart() { this.fetchFlowCollectionStart(flowSequenceStartToken); }
  fetchFlowMappingStart() { this.fetchFlowCollectionStart(flowMappingStartToken); }

  fetchFlowCollectionStart(make) {
    this.savePossibleSimpleKey();
    this.flowLevel += 1;
    this.allowSimpleKey = true;
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(make(startMark, this.getMark()));
  }

  fetchFlowSequenceEnd() { this.fetchFlowCollectionEnd(flowSequenceEndToken); }
  fetchFlowMappingEnd() { this.fetchFlowCollectionEnd(flowMappingEndToken); }

  fetchFlowCollectionEnd(make) {
    this.removePossibleSimpleKey();
    this.flowLevel -= 1;
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(make(startMark, this.getMark()));
  }

  fetchFlowEntry() {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(flowEntryToken(startMark, this.getMark()));
  }

  fetchBlockEntry() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null,
          'sequence entries are not allowed here', this.getMark());
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(blockSequenceStartToken(mark, mark));
      }
    }
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(blockEntryToken(startMark, this.getMark()));
  }

  fetchKey() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null,
          'mapping keys are not allowed here', this.getMark());
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(blockMappingStartToken(mark, mark));
      }
    }
    this.allowSimpleKey = !this.flowLevel;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(keyToken(startMark, this.getMark()));
  }

  fetchValue() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      this.possibleSimpleKeys.delete(this.flowLevel);
      this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
        keyToken(key.mark, key.mark));
      if (!this.flowLevel) {
        if (this.addIndent(key.column)) {
          this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
            blockMappingStartToken(key.mark, key.mark));
        }
      }
      this.allowSimpleKey = false;
    } else {
      if (!this.flowLevel) {
        if (!this.allowSimpleKey) {
          throw new ScannerError(null, null,
            'mapping values are not allowed here', this.getMark());
        }
        if (this.addIndent(this.column)) {
          const mark = this.getMark();
          this.tokens.push(blockMappingStartToken(mark, mark));
        }
      }
      this.allowSimpleKey = !this.flowLevel;
      this.removePossibleSimpleKey();
    }
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(valueToken(startMark, this.getMark()));
  }

  fetchAlias() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(aliasToken));
  }

  fetchAnchor() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(anchorToken));
  }

  fetchTag() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanTag());
  }

  fetchLiteral() { this.fetchBlockScalar('|'); }
  fetchFolded() { this.fetchBlockScalar('>'); }

  fetchBlockScalar(style) {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    this.tokens.push(this.scanBlockScalar(style));
  }

  fetchSingle() { this.fetchFlowScalar("'"); }
  fetchDouble() { this.fetchFlowScalar('"'); }

  fetchFlowScalar(style) {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanFlowScalar(style));
  }

  fetchPlain() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanPlain());
  }

  // -- Checkers ------------------------------------------------------------

  checkDirective() {
    return this.column === 0;
  }

  checkDocumentStart() {
    return this.column === 0 && this.prefix(3) === '---' &&
      isIn(this.peek(3), NULL_BL_T_LINEBR);
  }

  checkDocumentEnd() {
    return this.column === 0 && this.prefix(3) === '...' &&
      isIn(this.peek(3), NULL_BL_T_LINEBR);
  }

  checkBlockEntry() {
    return isIn(this.peek(1), NULL_BL_T_LINEBR);
  }

  checkKey() {
    if (this.flowLevel) return true;
    return isIn(this.peek(1), NULL_BL_T_LINEBR);
  }

  checkValue() {
    if (this.flowLevel) return true;
    return isIn(this.peek(1), NULL_BL_T_LINEBR);
  }

  checkPlain() {
    const ch = this.peek();
    return !isIn(ch, NULL_BL_T_LINEBR + '-?:,[]{}#&*!|>\'"%@`') ||
      (!isIn(this.peek(1), NULL_BL_T_LINEBR) &&
        (ch === '-' || (!this.flowLevel && isIn(ch, '?:'))));
  }

  // -- Scanners ------------------------------------------------------------

  scanToNextToken() {
    if (this.index === 0 && this.peek() === BOM) this.forward();
    let found = false;
    while (!found) {
      while (this.peek() === ' ') this.forward();
      if (this.peek() === '#') {
        while (!isIn(this.peek(), NULL_OR_LINEBR)) this.forward();
      }
      if (this.scanLineBreak()) {
        if (!this.flowLevel) this.allowSimpleKey = true;
      } else {
        found = true;
      }
    }
  }

  scanDirective() {
    const startMark = this.getMark();
    this.forward();
    const name = this.scanDirectiveName(startMark);
    let value = null;
    let endMark;
    if (name === 'YAML') {
      value = this.scanYamlDirectiveValue(startMark);
      endMark = this.getMark();
    } else if (name === 'TAG') {
      value = this.scanTagDirectiveValue(startMark);
      endMark = this.getMark();
    } else {
      endMark = this.getMark();
      while (!isIn(this.peek(), NULL_OR_LINEBR)) this.forward();
    }
    this.scanDirectiveIgnoredLine(startMark);
    return directiveToken(name, value, startMark, endMark);
  }

  scanDirectiveName(startMark) {
    let length = 0;
    let ch = this.peek(length);
    while (isAlnumOrDash(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected alphabetic or numeric character, but found ' + strRepr(ch),
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!isIn(ch, NULL_BL_LINEBR)) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected alphabetic or numeric character, but found ' + strRepr(ch),
        this.getMark());
    }
    return value;
  }

  scanYamlDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const major = this.scanYamlDirectiveNumber(startMark);
    if (this.peek() !== '.') {
      throw new ScannerError('while scanning a directive', startMark,
        "expected a digit or '.', but found " + strRepr(this.peek()),
        this.getMark());
    }
    this.forward();
    const minor = this.scanYamlDirectiveNumber(startMark);
    if (!isIn(this.peek(), NULL_BL_LINEBR)) {
      throw new ScannerError('while scanning a directive', startMark,
        "expected a digit or ' ', but found " + strRepr(this.peek()),
        this.getMark());
    }
    return [major, minor];
  }

  scanYamlDirectiveNumber(startMark) {
    const ch = this.peek();
    if (!isDigit(ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected a digit, but found ' + strRepr(ch), this.getMark());
    }
    let length = 0;
    while (isDigit(this.peek(length))) length += 1;
    const value = Number(this.prefix(length));
    this.forward(length);
    return value;
  }

  scanTagDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const handle = this.scanTagDirectiveHandle(startMark);
    while (this.peek() === ' ') this.forward();
    const prefix = this.scanTagDirectivePrefix(startMark);
    return [handle, prefix];
  }

  scanTagDirectiveHandle(startMark) {
    const value = this.scanTagHandle('directive', startMark);
    const ch = this.peek();
    if (ch !== ' ') {
      throw new ScannerError('while scanning a directive', startMark,
        "expected ' ', but found " + strRepr(ch), this.getMark());
    }
    return value;
  }

  scanTagDirectivePrefix(startMark) {
    const value = this.scanTagUri('directive', startMark);
    const ch = this.peek();
    if (!isIn(ch, NULL_BL_LINEBR)) {
      throw new ScannerError('while scanning a directive', startMark,
        "expected ' ', but found " + strRepr(ch), this.getMark());
    }
    return value;
  }

  scanDirectiveIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!isIn(this.peek(), NULL_OR_LINEBR)) this.forward();
    }
    const ch = this.peek();
    if (!isIn(ch, NULL_OR_LINEBR)) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected a comment or a line break, but found ' + strRepr(ch),
        this.getMark());
    }
    this.scanLineBreak();
  }

  scanAnchor(make) {
    const startMark = this.getMark();
    const indicator = this.peek();
    const name = indicator === '*' ? 'alias' : 'anchor';
    this.forward();
    let length = 0;
    let ch = this.peek(length);
    while (isAlnumOrDash(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError('while scanning an ' + name, startMark,
        'expected alphabetic or numeric character, but found ' + strRepr(ch),
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!isIn(ch, NULL_BL_T_LINEBR + '?:,]}%@`')) {
      throw new ScannerError('while scanning an ' + name, startMark,
        'expected alphabetic or numeric character, but found ' + strRepr(ch),
        this.getMark());
    }
    return make(value, startMark, this.getMark());
  }

  scanTag() {
    const startMark = this.getMark();
    let ch = this.peek(1);
    let handle;
    let suffix;
    if (ch === '<') {
      handle = null;
      this.forward(2);
      suffix = this.scanTagUri('tag', startMark);
      if (this.peek() !== '>') {
        throw new ScannerError('while parsing a tag', startMark,
          "expected '>', but found " + strRepr(this.peek()), this.getMark());
      }
      this.forward();
    } else if (isIn(ch, NULL_BL_T_LINEBR)) {
      handle = null;
      suffix = '!';
      this.forward();
    } else {
      let length = 1;
      let useHandle = false;
      while (!isIn(ch, NULL_BL_LINEBR)) {
        if (ch === '!') {
          useHandle = true;
          break;
        }
        length += 1;
        ch = this.peek(length);
      }
      if (useHandle) {
        handle = this.scanTagHandle('tag', startMark);
      } else {
        handle = '!';
        this.forward();
      }
      suffix = this.scanTagUri('tag', startMark);
    }
    ch = this.peek();
    if (!isIn(ch, NULL_BL_LINEBR)) {
      throw new ScannerError('while scanning a tag', startMark,
        "expected ' ', but found " + strRepr(ch), this.getMark());
    }
    return tagToken([handle, suffix], startMark, this.getMark());
  }

  scanBlockScalar(style) {
    const folded = style === '>';
    let chunks = [];
    const startMark = this.getMark();
    this.forward();
    const [chomping, increment] = this.scanBlockScalarIndicators(startMark);
    this.scanBlockScalarIgnoredLine(startMark);

    let minIndent = this.indent + 1;
    if (minIndent < 1) minIndent = 1;
    let indent;
    let breaks;
    let endMark;
    if (increment === null) {
      const scanned = this.scanBlockScalarIndentation();
      breaks = scanned[0];
      endMark = scanned[2];
      indent = Math.max(minIndent, scanned[1]);
    } else {
      indent = minIndent + increment - 1;
      const scanned = this.scanBlockScalarBreaks(indent);
      breaks = scanned[0];
      endMark = scanned[1];
    }
    let lineBreak = '';

    while (this.column === indent && this.peek() !== '\0') {
      chunks = chunks.concat(breaks);
      const leadingNonSpace = !isIn(this.peek(), ' \t');
      let length = 0;
      while (!isIn(this.peek(length), NULL_OR_LINEBR)) length += 1;
      chunks.push(this.prefix(length));
      this.forward(length);
      lineBreak = this.scanLineBreak();
      const scanned = this.scanBlockScalarBreaks(indent);
      breaks = scanned[0];
      endMark = scanned[1];
      if (this.column === indent && this.peek() !== '\0') {
        if (folded && lineBreak === '\n' && leadingNonSpace &&
          !isIn(this.peek(), ' \t')) {
          if (!breaks.length) chunks.push(' ');
        } else {
          chunks.push(lineBreak);
        }
      } else {
        break;
      }
    }

    if (chomping !== false) chunks.push(lineBreak);
    if (chomping === true) chunks = chunks.concat(breaks);

    return scalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanBlockScalarIndicators(startMark) {
    let chomping = null;
    let increment = null;
    let ch = this.peek();
    if (isIn(ch, '+-')) {
      chomping = ch === '+';
      this.forward();
      ch = this.peek();
      if (isDigit(ch)) {
        increment = Number(ch);
        if (increment === 0) {
          throw new ScannerError('while scanning a block scalar', startMark,
            'expected indentation indicator in the range 1-9, but found 0',
            this.getMark());
        }
        this.forward();
      }
    } else if (isDigit(ch)) {
      increment = Number(ch);
      if (increment === 0) {
        throw new ScannerError('while scanning a block scalar', startMark,
          'expected indentation indicator in the range 1-9, but found 0',
          this.getMark());
      }
      this.forward();
      ch = this.peek();
      if (isIn(ch, '+-')) {
        chomping = ch === '+';
        this.forward();
      }
    }
    ch = this.peek();
    if (!isIn(ch, NULL_BL_LINEBR)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        'expected chomping or indentation indicators, but found ' + strRepr(ch),
        this.getMark());
    }
    return [chomping, increment];
  }

  scanBlockScalarIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!isIn(this.peek(), NULL_OR_LINEBR)) this.forward();
    }
    const ch = this.peek();
    if (!isIn(ch, NULL_OR_LINEBR)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        'expected a comment or a line break, but found ' + strRepr(ch),
        this.getMark());
    }
    this.scanLineBreak();
  }

  scanBlockScalarIndentation() {
    const chunks = [];
    let maxIndent = 0;
    let endMark = this.getMark();
    while (isIn(this.peek(), ' ' + FULL_LINEBR)) {
      if (this.peek() !== ' ') {
        chunks.push(this.scanLineBreak());
        endMark = this.getMark();
      } else {
        this.forward();
        if (this.column > maxIndent) maxIndent = this.column;
      }
    }
    return [chunks, maxIndent, endMark];
  }

  scanBlockScalarBreaks(indent) {
    const chunks = [];
    let endMark = this.getMark();
    while (this.column < indent && this.peek() === ' ') this.forward();
    while (isIn(this.peek(), FULL_LINEBR)) {
      chunks.push(this.scanLineBreak());
      endMark = this.getMark();
      while (this.column < indent && this.peek() === ' ') this.forward();
    }
    return [chunks, endMark];
  }

  scanFlowScalar(style) {
    const double = style === '"';
    let chunks = [];
    const startMark = this.getMark();
    const quote = this.peek();
    this.forward();
    chunks = chunks.concat(this.scanFlowScalarNonSpaces(double, startMark));
    while (this.peek() !== quote) {
      chunks = chunks.concat(this.scanFlowScalarSpaces(double, startMark));
      chunks = chunks.concat(this.scanFlowScalarNonSpaces(double, startMark));
    }
    this.forward();
    return scalarToken(chunks.join(''), false, startMark, this.getMark(), style);
  }

  scanFlowScalarNonSpaces(double, startMark) {
    const chunks = [];
    for (;;) {
      let length = 0;
      while (!isIn(this.peek(length), '\'"\\' + NULL_BL_T_LINEBR)) length += 1;
      if (length) {
        chunks.push(this.prefix(length));
        this.forward(length);
      }
      let ch = this.peek();
      if (!double && ch === "'" && this.peek(1) === "'") {
        chunks.push("'");
        this.forward(2);
      } else if ((double && ch === "'") || (!double && isIn(ch, '"\\'))) {
        chunks.push(ch);
        this.forward();
      } else if (double && ch === '\\') {
        this.forward();
        ch = this.peek();
        if (ESCAPE_REPLACEMENTS.has(ch)) {
          chunks.push(ESCAPE_REPLACEMENTS.get(ch));
          this.forward();
        } else if (ESCAPE_CODES.has(ch)) {
          length = ESCAPE_CODES.get(ch);
          this.forward();
          for (let k = 0; k < length; k++) {
            if (!isIn(this.peek(k), HEX_DIGITS)) {
              throw new ScannerError('while scanning a double-quoted scalar',
                startMark,
                'expected escape sequence of ' + length +
                ' hexadecimal numbers, but found ' + strRepr(this.peek(k)),
                this.getMark());
            }
          }
          const code = parseInt(this.prefix(length), 16);
          chunks.push(fromCodePointLoose(code));
          this.forward(length);
        } else if (isIn(ch, FULL_LINEBR)) {
          this.scanLineBreak();
          for (const chunk of this.scanFlowScalarBreaks(double, startMark)) {
            chunks.push(chunk);
          }
        } else {
          throw new ScannerError('while scanning a double-quoted scalar',
            startMark, 'found unknown escape character ' + strRepr(ch),
            this.getMark());
        }
      } else {
        return chunks;
      }
    }
  }

  scanFlowScalarSpaces(double, startMark) {
    const chunks = [];
    let length = 0;
    while (isIn(this.peek(length), ' \t')) length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (ch === '\0') {
      throw new ScannerError('while scanning a quoted scalar', startMark,
        'found unexpected end of stream', this.getMark());
    } else if (isIn(ch, FULL_LINEBR)) {
      const lineBreak = this.scanLineBreak();
      const breaks = this.scanFlowScalarBreaks(double, startMark);
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (!breaks.length) chunks.push(' ');
      for (const chunk of breaks) chunks.push(chunk);
    } else {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanFlowScalarBreaks(double, startMark) {
    const chunks = [];
    for (;;) {
      const prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') &&
        isIn(this.peek(3), NULL_BL_T_LINEBR)) {
        throw new ScannerError('while scanning a quoted scalar', startMark,
          'found unexpected document separator', this.getMark());
      }
      while (isIn(this.peek(), ' \t')) this.forward();
      if (isIn(this.peek(), FULL_LINEBR)) chunks.push(this.scanLineBreak());
      else return chunks;
    }
  }

  scanPlain() {
    let chunks = [];
    const startMark = this.getMark();
    let endMark = startMark;
    const indent = this.indent + 1;
    let spaces = [];
    for (;;) {
      let length = 0;
      if (this.peek() === '#') break;
      for (;;) {
        const ch = this.peek(length);
        if (isIn(ch, NULL_BL_T_LINEBR) ||
          (ch === ':' && isIn(this.peek(length + 1),
            NULL_BL_T_LINEBR + (this.flowLevel ? ',[]{}' : ''))) ||
          (this.flowLevel && isIn(ch, ',?[]{}'))) {
          break;
        }
        length += 1;
      }
      if (length === 0) break;
      this.allowSimpleKey = false;
      chunks = chunks.concat(spaces);
      chunks.push(this.prefix(length));
      this.forward(length);
      endMark = this.getMark();
      spaces = this.scanPlainSpaces(indent, startMark);
      if (spaces === null || spaces.length === 0 || this.peek() === '#' ||
        (!this.flowLevel && this.column < indent)) {
        break;
      }
    }
    return scalarToken(chunks.join(''), true, startMark, endMark);
  }

  scanPlainSpaces(indent, startMark) {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === ' ') length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (isIn(ch, FULL_LINEBR)) {
      const lineBreak = this.scanLineBreak();
      this.allowSimpleKey = true;
      let prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') &&
        isIn(this.peek(3), NULL_BL_T_LINEBR)) {
        return null;
      }
      const breaks = [];
      while (isIn(this.peek(), ' ' + FULL_LINEBR)) {
        if (this.peek() === ' ') {
          this.forward();
        } else {
          breaks.push(this.scanLineBreak());
          prefix = this.prefix(3);
          if ((prefix === '---' || prefix === '...') &&
            isIn(this.peek(3), NULL_BL_T_LINEBR)) {
            return null;
          }
        }
      }
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (!breaks.length) chunks.push(' ');
      for (const brk of breaks) chunks.push(brk);
    } else if (whitespaces) {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanTagHandle(name, startMark) {
    let ch = this.peek();
    if (ch !== '!') {
      throw new ScannerError('while scanning a ' + name, startMark,
        "expected '!', but found " + strRepr(ch), this.getMark());
    }
    let length = 1;
    ch = this.peek(length);
    if (ch !== ' ') {
      while (isAlnumOrDash(ch)) {
        length += 1;
        ch = this.peek(length);
      }
      if (ch !== '!') {
        this.forward(length);
        throw new ScannerError('while scanning a ' + name, startMark,
          "expected '!', but found " + strRepr(ch), this.getMark());
      }
      length += 1;
    }
    const value = this.prefix(length);
    this.forward(length);
    return value;
  }

  scanTagUri(name, startMark) {
    const chunks = [];
    let length = 0;
    let ch = this.peek(length);
    while (isAlnumOrDash(ch) || isIn(ch, "-;/?:@&=+$,_.!~*'()[]%")) {
      if (ch === '%') {
        chunks.push(this.prefix(length));
        this.forward(length);
        length = 0;
        chunks.push(this.scanUriEscapes(name, startMark));
      } else {
        length += 1;
      }
      ch = this.peek(length);
    }
    if (length) {
      chunks.push(this.prefix(length));
      this.forward(length);
      length = 0;
    }
    if (!chunks.length) {
      throw new ScannerError('while parsing a ' + name, startMark,
        'expected URI, but found ' + strRepr(ch), this.getMark());
    }
    return chunks.join('');
  }

  scanUriEscapes(name, startMark) {
    const codes = [];
    const mark = this.getMark();
    while (this.peek() === '%') {
      this.forward();
      for (let k = 0; k < 2; k++) {
        if (!isIn(this.peek(k), HEX_DIGITS)) {
          throw new ScannerError('while scanning a ' + name, startMark,
            'expected URI escape sequence of 2 hexadecimal numbers, but found ' +
            strRepr(this.peek(k)), this.getMark());
        }
      }
      codes.push(parseInt(this.prefix(2), 16));
      this.forward(2);
    }
    try {
      return new TextDecoder('utf-8', { fatal: true })
        .decode(Uint8Array.from(codes));
    } catch (err) {
      throw new ScannerError('while scanning a ' + name, startMark,
        'invalid utf-8 byte sequence', mark);
    }
  }

  scanLineBreak() {
    const ch = this.peek();
    if (isIn(ch, '\r\n' + NEL)) {
      if (this.prefix(2) === '\r\n') this.forward(2);
      else this.forward();
      return '\n';
    }
    if (isIn(ch, LS + PS)) {
      this.forward();
      return ch;
    }
    return '';
  }
}

// chr() accepts lone surrogates in Python; String.fromCodePoint does too as
// long as the value is below 0x110000.
function fromCodePointLoose(code) {
  if (code > 0x10ffff) return String.fromCharCode(0xfffd);
  return String.fromCodePoint(code);
}

export { TOKEN };

